#!/usr/bin/env node
// Connection capability checker — generated by the catalog compiler.
//
// Usage:
//   node scripts/check-connections.mjs
//
// Reads connections.json and reports per-action readiness:
//   mcp        — HEAD-probes the server (no auth): reachable / unreachable.
//                Read-verified and scope-confirmed-write require a probe-auth run.
//                A local server has no URL: Claude Code starts it from
//                .mcp.json, so it is listed with its command, not probed.
//                A claude.ai connector has no URL either: it is connected in
//                claude.ai, so it is listed, not probed.
//   systems    — each board system: bound to a connector, or not connected.
//   api-script — checks adapter file present and credential env var is set.
//   handoff    — manual; no automated check.
// Also reports every credential env var (bearer tokens used in .mcp.json
// headers, and API keys an adapter script reads) as set or missing, never
// the value.
//
// Exits 1 if any mcp or api-script connection is not reachable/configured,
// or any required env var is missing.

import { readFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
// Header tokens for .mcp.json must already be in the environment Claude Code
// started with; setup/.env is not read for them. Snapshot before loading it.
const exportedBeforeStart = new Set(Object.keys(process.env));

// Loads setup/.env into process.env if present. Does not override a value
// already set, and never prints what it loaded.
const envPath = join(root, "setup", ".env");
if (existsSync(envPath)) {
  for (const line of readFileSync(envPath, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed.slice(eq + 1).trim();
    if (key && !(key in process.env)) process.env[key] = value;
  }
}

const { connections, systems = [] } = JSON.parse(readFileSync(join(root, "connections.json"), "utf8"));

let failures = 0;
const lines = [];

// Board systems: bound to a connector, or still unset. An unset system the
// workflow writes is a failure: the step that writes it cannot run.
for (const sc of systems) {
  const actions = sc.actions.length ? sc.actions.join(", ") : "no actions declared";
  if (sc.status === "bound" && sc.connector === "local-file") {
    const where = sc.location ? join(root, sc.location) : null;
    if (where && !existsSync(where)) {
      failures++;
      lines.push(`  ✗  ${sc.name} — a file in this folder, but ${sc.location} does not exist (${actions})`);
    } else {
      lines.push(`  ✓  ${sc.name} — a file in this folder${sc.location ? `: ${sc.location}` : ""} (${actions})`);
    }
  } else if (sc.status === "bound") {
    lines.push(`  ✓  ${sc.name} — bound to ${sc.connectorName} (${actions})${sc.location ? `; location: ${sc.location}` : "; which one is not recorded: ask, then add it as the third argument of bind-system"}`);
  } else {
    failures++;
    lines.push(`  ✗  ${sc.name} — not connected (${actions}). Ask where it lives, then: node scripts/bind-system.mjs ${sc.systemId} <connector> [location]`);
  }
}

const REQUIRED_ENV_VARS = [];
for (const { name, where } of REQUIRED_ENV_VARS) {
  if (where === "process" && !exportedBeforeStart.has(name)) {
    failures++;
    lines.push(
      process.env[name]
        ? `  ✗  ${name} — in setup/.env, but Claude Code cannot read it from there. Export it before starting Claude Code (README.md says how).`
        : `  ✗  ${name} — missing. Export it before starting Claude Code (README.md says how); setup/.env is not read for this one.`,
    );
  } else if (process.env[name]) {
    lines.push(`  ✓  ${name} — set`);
  } else {
    failures++;
    lines.push(`  ✗  ${name} — missing`);
  }
}

for (const conn of connections) {
  for (const action of conn.actions) {
    const label = `${conn.name} / ${action.actionId}`;

    if (action.route === "handoff") {
      const note = action.runtimeFallbackReason ? ` [${action.runtimeFallbackReason}]` : "";
      lines.push(`  –  ${label} — handoff (manual)${note}`);
      continue;
    }

    if (action.route === "api-script") {
      const adapterPath = action.adapter ? join(root, action.adapter) : null;
      if (!adapterPath || !existsSync(adapterPath)) {
        failures++;
        lines.push(`  ✗  ${label} — adapter not found: ${action.adapter ?? "(none)"}`);
      } else {
        lines.push(`  ✓  ${label} — api-script (adapter present; write unverified without contract test)`);
      }
      continue;
    }

    if (action.route === "mcp") {
      if (conn.connector === "claude-ai") {
        lines.push(`  –  ${label} — claude.ai connector (connect it in claude.ai and enable it for the session); not probed`);
        continue;
      }
      if (action.mcpCommand) {
        lines.push(`  –  ${label} — local server, started by Claude Code from .mcp.json (${action.mcpCommand}); not probed`);
        continue;
      }
      if (!action.mcpUrl) {
        failures++;
        lines.push(`  ✗  ${label} — no MCP server URL recorded for this tool`);
        continue;
      }
      const url = action.mcpUrl;
      try {
        const res = await fetch(url, { method: "HEAD", signal: AbortSignal.timeout(5000) });
        // 401/403/405 means the server responded — it exists, auth is required.
        if (res.ok || res.status === 401 || res.status === 403 || res.status === 405) {
          lines.push(`  ✓  ${label} — mcp server reachable (read unverified, write unverified — run probe-auth to confirm)`);
        } else {
          failures++;
          lines.push(`  ✗  ${label} — mcp server returned ${res.status}`);
        }
      } catch (e) {
        failures++;
        lines.push(`  ✗  ${label} — mcp unreachable: ${e.message}`);
      }
    }
  }
}

console.log(lines.join("\n"));
if (failures > 0) {
  console.log(`\n${failures} item(s) need attention before deployment.`);
  process.exit(1);
} else {
  console.log("\nAll connections and env vars accounted for.");
}
